## 5️⃣ Full‑page example (copy‑paste)

If you just want a runnable demo, paste the following into a file `index.html` and open it in a browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>MapLibre flyTo demo</title>
  <link href="https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.css" rel="stylesheet"/>
  <style>
    html,body{margin:0;height:100%;}
    #map{position:absolute;top:0;bottom:0;width:100%;}
    .control{
      position:absolute;top:10px;left:10px;
      background:rgba(255,255,255,0.9);
      padding:6px 10px;border-radius:4px;
      font-family:sans-serif;
    }
  </style>
</head>
<body>
<div id="map"></div>
<div class="control">
  <button id="flyBtn">Fly to San Francisco</button>
  <div id="flyStatus" aria-live="polite" style="position:absolute; left:-9999px;"></div>
</div>

<script src="https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.js"></script>
<script>
  const map = new maplibregl.Map({
    container: 'map',
    style: 'https://demotiles.maplibre.org/style.json',
    center: [-122.447303, 37.753574],
    zoom: 12,
    pitch: 45,
    bearing: 0,
    antialias: true
  });

  function getFlyOptions(target){
    return {
      center: target.center,
      zoom: target.zoom ?? map.getZoom(),
      bearing: target.bearing ?? map.getBearing(),
      pitch: target.pitch ?? map.getPitch(),
      curve: 0.25,
      duration: 1000,
      essential: true
    };
  }

  function flyToSF(){
    const target = {
      center: [-122.4194, 37.7749],
      zoom: 14,
      pitch: 60,
      bearing: 30
    };
    map.flyTo(getFlyOptions(target));

    const status = document.getElementById('flyStatus');
    status.textContent = 'Map moved to San Francisco';
    document.getElementById('flyBtn').focus();
  }

  document.getElementById('flyBtn').addEventListener('click', flyToSF);
</script>
</body>
</html>
```

Open the file, click **“Fly to San Francisco”**, and watch the camera glide smoothly while the map’s labels and symbols stay legible.

---

### TL;DR

```js
map.flyTo({
  center: [lon, lat],
  zoom: 14,               // optional
  bearing: 30,            // optional
  pitch: 60,              // optional
  curve: 0.25,            // easing curve (default)
  duration: 1000,         // ms
  essential: true         // respects reduced‑motion
});
```

Hook that call to a button’s `click` event, add an ARIA live region for accessibility, and you have a polished, cartographically sound “fly‑to” interaction. Happy mapping!
